VA, MA, SE = "Virginia", "Mid-Atlantic", "Southeast"
regions = [
 region("us", VA, 37.9, -78.6, 7.0,
 "Where English colonists were ordered to plant vines in 1619, and where Jefferson failed so the state could succeed.",
 "Virginia has more than 300 wineries and roughly 4,000 to 5,000 acres of vines, concentrated in the Piedmont along the Blue Ridge, where elevation and hillside air drainage reduce the humidity, frost and disease that plague the eastern lowlands. The state has 9 AVAs. Its best wines are Cabernet Franc, Petit Verdot, Bordeaux blends, Viognier (promoted as the state grape) and Petit Manseng, plus the native Norton.",
 "In 1619 the first General Assembly of the Virginia colony, meeting at Jamestown, passed Acte 12, requiring every householder to plant and tend at least ten vines, and the Virginia Company sent French vignerons from Languedoc. Vinifera died of phylloxera, mildews and Pierce's disease, though the colonists did not know why. Thomas Jefferson planted European vines at Monticello from 1770 and backed Philip Mazzei's Tuscan vineyard nearby (1774); none succeeded. Around 1820 to 1830 Dr. Daniel Norton of Richmond introduced the Norton grape, a native American variety, and Norton from Virginia and Missouri won medals in Europe in the 1870s.\n\nThe modern era began in the 1970s; the Zonin family of Italy founded Barboursville Vineyards in 1976 on the ruins of Governor James Barbour's estate, whose mansion Jefferson designed. Virginia now draws wine tourism to Charlottesville, Loudoun County and the Shenandoah Valley.",
 "Humid continental to subtropical climate with summer rain; the Blue Ridge foothills give elevation and air drainage. Clay-rich, granitic and greenstone soils in the Piedmont; limestone in the Shenandoah Valley.",
 "Cabernet Franc, Petit Verdot, Merlot, Cabernet Sauvignon, Viognier, Petit Manseng, Chardonnay, Norton, Tannat.",
 "Bordeaux-style blends; Viognier and Petit Manseng; sparkling wine; Norton.",
 "Federal AVA rules; Virginia sets no stricter standards but has a Governor's Cup competition and Virginia Wine Board programmes.",
 ["Monticello", "Middleburg Virginia", "Shenandoah Valley", "Virginia's Eastern Shore", "Northern Neck George Washington Birthplace", "Virginia Peninsula", "Rocky Knob", "North Fork of Roanoke", "Appalachian High Country"], SRC, parent=None),
 region("us", MA, 40.2, -76.0, 6.8,
 "Pennsylvania, New Jersey and Maryland: colonial wine dreams and a modern coastal-plain revival.",
 "The Mid-Atlantic states have long winemaking histories and growing modern industries. New Jersey's sandy Outer Coastal Plain and Cape May Peninsula, Pennsylvania's Lehigh and Lancaster valleys and Lake Erie shore, and Maryland's Piedmont AVAs grow vinifera, hybrids and natives. Pennsylvania is one of the larger grape-growing states thanks to Concord on Lake Erie.",
 "William Penn tried to plant French vines near Philadelphia in 1683. James Alexander, gardener to the Penn family, found the Alexander grape near Philadelphia in the 1740s, a chance cross of a native vine with a European one and the first hybrid grape in America. New Jersey's Renault Winery (1864) at Egg Harbor City is one of the oldest continuously operating wineries in the country.",
 "Varied: sandy coastal plain, Piedmont clays, limestone valleys; humid summers.",
 "Chardonnay, Cabernet Franc, Merlot, Albariño, Chambourcin, Vidal, Concord.",
 "Bordeaux-style reds, aromatic whites, sparkling.", "Federal AVAs.",
 ["Outer Coastal Plain", "Cape May Peninsula", "Warren Hills", "Central Delaware Valley", "Lancaster Valley", "Lehigh Valley", "Cumberland Valley", "Catoctin", "Linganore"], SRC, parent=None),
 region("us", SE, 35.3, -82.0, 6.6,
 "Muscadine country, mountain vinifera and the oldest cultivated vine in America.",
 "The humid Southeast is the home of the muscadine (Vitis rotundifolia), the native grape that resists Pierce's disease and produces sweet, musky wines from Scuppernong and other varieties. In the cooler Blue Ridge and Appalachian highlands, growers plant vinifera and hybrids. North Carolina has seven AVAs, Georgia two, Tennessee four (including shared ones).",
 "Giovanni da Verrazzano recorded abundant grapes on the North Carolina coast in 1524, and Sir Walter Raleigh's captains Amadas and Barlowe wrote in 1584 that the coast was 'so full of grapes'. The Mother Vine on Roanoke Island, a Scuppernong, is reputed to be about 400 years old. Garrett & Company's 'Virginia Dare' wine, first made from Scuppernong in North Carolina, was one of America's best-selling wines before Prohibition. In Georgia, the 1880 census ranked it among the leading wine states.",
 "Humid subtropical lowlands; Appalachian highlands with thermal belts on slopes.",
 "Scuppernong and other muscadines, Chambourcin, Cabernet Franc, Viognier, Petit Manseng, Chardonnay, Merlot, Vidal.",
 "Sweet muscadine wines; mountain reds and whites.", "Federal AVAs.",
 ["Yadkin Valley", "Swan Creek", "Haw River Valley", "Crest of the Blue Ridge Henderson County", "Tryon Foothills", "Upper Hiwassee Highlands", "Dahlonega Plateau", "Appalachian High Country", "Upper Cumberland", "Nine Lakes of East Tennessee", "Mississippi Delta"], SRC, parent=None)]

A = []
A.append(ava("Monticello", VA, "Virginia's most important AVA (1984, expanded 2018), around Charlottesville in the Piedmont foothills of the Blue Ridge, named for Thomas Jefferson's home. Jefferson's vinifera failed, but modern growers on well-drained, clay-rich slopes make Virginia's best Cabernet Franc, Petit Verdot, Viognier and Bordeaux blends. Barboursville, Early Mountain, King Family, Jefferson Vineyards and Michael Shaps are leading producers.", sub="Virginia", styles=["red", "white", "sparkling"], dom="red", grapes="Cabernet Franc, Petit Verdot, Merlot, Viognier, Petit Manseng, Chardonnay", producers=["Barboursville", "Early Mountain", "King Family", "Jefferson Vineyards", "Michael Shaps", "Keswick", "Veritas"], nerd="Jefferson Vineyards grows on land that Jefferson gave to Philip Mazzei for his 1774 vineyard experiment."))
A.append(ava("Middleburg Virginia", VA, "An AVA (2012) of about 190 square miles in Loudoun and Fauquier counties, horse country an hour from Washington, D.C. At approval it had 10 vineyards and 14 wineries. Cabernet Franc, Petit Verdot and Chardonnay; Boxwood and RdV (founded by Rutger de Vink) make some of Virginia's most serious Bordeaux blends nearby.", sub="Virginia", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Petit Verdot, Merlot, Chardonnay, Viognier", producers=["Boxwood", "Greenhill", "Chrysalis (nearby)", "Cana"]))
A.append(ava("Shenandoah Valley", VA, "A long limestone valley AVA (1982) between the Blue Ridge and the Allegheny Mountains in Virginia and West Virginia, drier than the Piedmont thanks to the rain shadow of the mountains. Riesling, Chardonnay, Cabernet Franc and hybrids; Bluestone and Barren Ridge are among its wineries. Not to be confused with California Shenandoah Valley.", sub="Virginia and West Virginia", styles=["white", "red"], dom="white", grapes="Chardonnay, Riesling, Cabernet Franc, Vidal, Chambourcin", producers=["Bluestone", "Barren Ridge", "Muse"]))
A.append(ava("Virginia's Eastern Shore", VA, "A coastal AVA (1990) on the Delmarva Peninsula between Chesapeake Bay and the Atlantic. Water on both sides moderates temperatures and extends the season; sandy soils. Chatham Vineyards on Church Creek is the leading winery.", sub="Virginia", styles=["white", "red"], dom="white", grapes="Chardonnay, Merlot, Cabernet Franc, Petit Verdot", producers=["Chatham Vineyards"], match=["Virginia’s Eastern Shore"]))
A.append(ava("Northern Neck George Washington Birthplace", VA, "An AVA (1987) on the Northern Neck peninsula between the Potomac and Rappahannock rivers, where George Washington was born in 1732. Rivers and the Chesapeake moderate the climate; Ingleside Vineyards, which petitioned for the AVA, is the leading winery.", sub="Virginia", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Chardonnay, Petit Verdot", producers=["Ingleside"]))
A.append(ava("Virginia Peninsula", VA, "A coastal AVA (2021) of about 673,000 acres between the James and York rivers, including Williamsburg and Jamestown, where Acte 12 ordered colonists to plant vines in 1619. It was petitioned by The Williamsburg Winery; at approval it had five vineyards on about 112 acres.", sub="Virginia", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Chardonnay, Petit Verdot", producers=["The Williamsburg Winery"]))
A.append(ava("Rocky Knob", VA, "A small, high AVA (1983) on the Blue Ridge plateau in Floyd and Patrick counties along the Blue Ridge Parkway, near Rocky Knob. Cool, elevated and wind-swept; Villa Appalaccia makes Italian varieties here.", sub="Virginia", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Sangiovese, Pinot Grigio", producers=["Villa Appalaccia"]))
A.append(ava("North Fork of Roanoke", VA, "A small AVA (1983) in the valley of the North Fork of the Roanoke River in Montgomery and Roanoke counties, in the Ridge and Valley region of southwestern Virginia. Very few vineyards today.", sub="Virginia", styles=["red", "white"], dom="red", grapes="Chardonnay, Cabernet Sauvignon"))
A.append(ava("Appalachian High Country", SE, "A high, mountainous AVA (2016) of about 2,400 square miles straddling North Carolina, Tennessee and Virginia around Boone, with vineyards from about 900 to 1,200 m, among the highest in the East. Short seasons and cold winters favour cold-hardy hybrids such as Marquette and Frontenac. At approval it had 21 vineyards (71 acres) and 10 wineries.", sub="North Carolina, Tennessee, Virginia", styles=["red", "white"], dom="red", grapes="Marquette, Frontenac, La Crescent, Riesling"))
A.append(ava("Outer Coastal Plain", MA, "New Jersey's largest AVA (2007, expanded 2017), about 2.25 million acres of sandy coastal plain in the southern half of the state. The Atlantic and Delaware Bay moderate the climate and give a long season; sandy, well-drained soils suit Cabernet Franc, Merlot, Chardonnay, Albariño and Chambourcin. Renault Winery at Egg Harbor City has operated since 1864.", sub="New Jersey", styles=["red", "white", "sparkling"], dom="red", grapes="Cabernet Franc, Merlot, Chardonnay, Albariño, Chambourcin", producers=["Renault", "Bellview", "Sharrott", "Tomasello"], contains=["Cape May Peninsula"]))
A.append(ava("Cape May Peninsula", MA, "A peninsula AVA (2018) at New Jersey's southern tip, surrounded by the Atlantic and Delaware Bay. The petition stressed its warmth: water keeps autumns mild and the frost-free season long. Sandy soils; at approval six vineyards on about 115 acres. Albariño, Merlot and Chardonnay.", sub="Outer Coastal Plain", styles=["white", "red"], dom="white", grapes="Albariño, Chardonnay, Merlot, Cabernet Franc", producers=["Cape May Winery", "Hawk Haven", "Willow Creek"]))
A.append(ava("Warren Hills", MA, "An AVA (1988) in the valleys of Warren County in northwestern New Jersey, where limestone valleys run between forested ridges of the Highlands. Cold winters favour hybrids such as Vidal and Chambourcin alongside cool-climate vinifera such as Chardonnay and Cabernet Franc.", sub="New Jersey", styles=["white", "red"], dom="white", grapes="Chardonnay, Cabernet Franc, Vidal, Chambourcin", producers=["Villa Milagro", "Brook Hollow"]))
A.append(ava("Central Delaware Valley", MA, "An AVA (1984) along both banks of the Delaware River in Pennsylvania (Bucks County) and New Jersey (Hunterdon and Mercer), sheltered by the valley; Unionville Vineyards and others make Chardonnay and Bordeaux varieties.", sub="New Jersey and Pennsylvania", styles=["white", "red"], dom="white", grapes="Chardonnay, Cabernet Franc, Chambourcin", producers=["Unionville Vineyards"]))
A.append(ava("Lancaster Valley", MA, "An AVA (1982) in Pennsylvania's Lancaster and Chester counties, in Pennsylvania Dutch farm country with deep, fertile limestone soils. Conestoga Vineyards petitioned for it; today wineries such as Waltz Vineyards grow Chardonnay and Bordeaux varieties alongside hybrids.", sub="Pennsylvania", styles=["white", "red"], dom="white", grapes="Vidal, Chambourcin, Chardonnay, Cabernet Franc", producers=["Nissley", "Waltz Vineyards"]))
A.append(ava("Lehigh Valley", MA, "An AVA (2008) of about a million acres in eastern Pennsylvania along the Lehigh River, named from a Lenape word for river forks. Rolling hills; at approval nine wineries and 220 acres. Galen Glen and Fox & Hound are known for Grüner Veltliner and Riesling.", sub="Pennsylvania", styles=["white", "red", "sparkling"], dom="white", grapes="Riesling, Grüner Veltliner, Chardonnay, Cabernet Franc, Chambourcin", producers=["Galen Glen", "Clover Hill", "Pinnacle Ridge", "Vynecrest"]))
A.append(ava("Cumberland Valley", MA, "An AVA (1985) in the limestone Cumberland Valley of south-central Pennsylvania and western Maryland, part of the Great Appalachian Valley that runs from New York to Alabama. The valley's sheltered floor and well-drained soils grow hybrids and vinifera for a handful of small wineries.", sub="Pennsylvania and Maryland", styles=["white", "red"], dom="white", grapes="Chardonnay, Vidal, Cabernet Franc"))
A.append(ava("Catoctin", MA, "A Piedmont AVA (1983) in Frederick and Washington counties, Maryland, at the foot of the Catoctin Mountains. Black Ankle and Sugarloaf Mountain are leading wineries nearby.", sub="Maryland", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Merlot, Chardonnay, Albariño", producers=["Catoctin Breeze", "Sugarloaf Mountain"]))
A.append(ava("Linganore", MA, "An AVA (1983) in Frederick and Carroll counties, Maryland, around Linganore Creek in the Piedmont. Linganore Winecellars (Berrywine Plantations), founded in 1976, petitioned for it and makes grape and fruit wines; the area grows hybrids and vinifera.", sub="Maryland", styles=["white", "red"], dom="white", grapes="Chardonnay, Vidal, Chambourcin", producers=["Linganore Winecellars"]))
A.append(ava("Yadkin Valley", SE, "North Carolina's first AVA (2002), about 1.4 million acres in the Piedmont along the Yadkin River northwest of Winston-Salem. Former tobacco farmers replanted with vinifera and hybrids; more than 40 wineries make Cabernet Franc, Merlot, Chardonnay and Viognier. Shelton Vineyards (1999) led the expansion.", sub="North Carolina", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Merlot, Chardonnay, Viognier, Chambourcin", producers=["Shelton", "Raffaldini", "Jones von Drehle", "RagApple Lassie"], contains=["Swan Creek"]))
A.append(ava("Swan Creek", SE, "A small sub-AVA (2008) of the Yadkin Valley in Wilkes, Yadkin and Iredell counties, with three wineries and 75 acres at approval; sandy-loam soils of the Brushy Mountains foothills.", sub="Yadkin Valley", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Merlot, Chardonnay, Sangiovese", producers=["Raffaldini", "Shadow Springs"]))
A.append(ava("Haw River Valley", SE, "A Piedmont AVA (2009) of about 868 square miles along the Haw River in central North Carolina, named for the Sissipahaw people. At approval it had about 60 acres and six wineries.", sub="North Carolina", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Chambourcin, Merlot, Viognier", producers=["Iron Gate", "Grove Winery"]))
A.append(ava("Crest of the Blue Ridge Henderson County", SE, "A mountain AVA (2019) of about 215 square miles in Henderson County near Hendersonville, defined by elevation (most land at 640 to 960 m) and a cooler climate. At approval it had 14 vineyards on about 70 acres and two bonded wineries.", sub="North Carolina", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Chardonnay, Petit Manseng, Riesling", producers=["Burntshirt", "Saint Paul Mountain"]))
A.append(ava("Tryon Foothills", SE, "A new AVA (effective October 2025) of about 176 square miles in Polk County, North Carolina, around Tryon and Columbus, on the escarpment where the Blue Ridge drops to the Piedmont. Its key feature is a thermal belt: on calm nights, cold air sinks to the valley floors and warmer air settles on the mid-slopes, so frost is rarer there. The petition placed 95 percent of the area in Winkler Region V; at approval it had five vineyards (about 78 acres) and four wineries.", sub="North Carolina", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Petit Verdot, Viognier, Chambourcin", producers=["Overmountain", "Parker-Binns", "Mountain Brook"], created="2025", lat=35.24, lon=-82.20))
A.append(ava("Upper Hiwassee Highlands", SE, "A mountain AVA (2014) of about 690 square miles in the Hiwassee River basin straddling Georgia and North Carolina. At approval 26 vineyards grew about 54 acres of hybrids, natives and vinifera, and five wineries were operating.", sub="Georgia and North Carolina", styles=["red", "white"], dom="red", grapes="Cabernet Franc, Chardonnay, Chambourcin, Traminette", producers=["Crane Creek", "Hightower Creek"]))
A.append(ava("Dahlonega Plateau", SE, "Georgia's first wholly in-state AVA (2018), about 133 square miles on a plateau in Lumpkin and White counties, the site of the 1829 Georgia gold rush. Elevation and slope give better air drainage than the surrounding land. At approval it had seven wineries and about 110 acres; Wolf Mountain, Frogtown and Three Sisters grow Cabernet, Petit Manseng and sparkling-wine grapes.", sub="Georgia", styles=["red", "white", "sparkling"], dom="red", grapes="Cabernet Sauvignon, Cabernet Franc, Petit Manseng, Chardonnay", producers=["Wolf Mountain", "Frogtown Cellars", "Three Sisters", "Montaluce"]))
A.append(ava("Upper Cumberland", SE, "A large AVA (2024) of about 2.19 million acres on the Highland Rim and Cumberland Plateau in Middle Tennessee, with 55 small vineyards (about 71 acres) and nine wineries at approval. The petition stressed limestone and sandstone geology, elevation, soils and climate.", sub="Tennessee", styles=["red", "white"], dom="red", grapes="Chambourcin, Cabernet Franc, Vidal, Muscadine"))
A.append(ava("Nine Lakes of East Tennessee", SE, "A large AVA (effective April 2026) of about 4,064 square miles in the Valley and Ridge Province of East Tennessee, named for the nine reservoirs created by Tennessee Valley Authority dams in the 14 counties around Knoxville. Parallel ridges (about 330 to 460 m) and valleys let growers choose slopes where morning sun dries the dew. At approval it had about 232 acres of vines and 29 wineries, many of them busy tourist wineries around the Great Smoky Mountains gateway towns.", sub="Tennessee", styles=["red", "white", "sweet"], dom="red", grapes="Chambourcin, Cabernet Franc, Muscadine, Vidal, Traminette", created="2026", lat=36.05, lon=-83.95))
A.append(ava("Mississippi Delta", SE, "A large alluvial AVA (1984) of about 4.1 million acres covering the Mississippi Delta in Mississippi, Louisiana and Tennessee. The Rushing Winery petitioned for it; muscadines dominate the little wine made here.", sub="Mississippi, Louisiana, Tennessee", styles=["white", "red", "sweet"], dom="sweet", grapes="Muscadine, Scuppernong"))

S = []
S.append(site("monticello", "us", "Thomas Jefferson's Monticello", "historic", "Monticello", 38.0086, -78.4532,
 "Jefferson planted European vines in the gardens below his house from 1770 and for decades tried to grow wine grapes, without success; he was also America's most ardent buyer of Bordeaux and Burgundy. The restored vineyard on the south terrace grows varieties he planted.", cls="UNESCO World Heritage Site", producers=[]))
S.append(site("barboursville", "us", "Barboursville Vineyards", "estate", "Monticello", 38.1605, -78.2772,
 "The Zonin family from Veneto founded Barboursville in 1976 on the estate of Governor James Barbour, whose 1814 mansion, designed by Jefferson, burned in 1884 and stands as a ruin. Gabriele Rausse planted vinifera here when experts said it was impossible; Octagon, its Bordeaux blend, is a Virginia classic.", cls="Founded 1976", producers=["Barboursville Vineyards"]))
S.append(site("jamestown", "us", "Jamestown (Acte 12, 1619)", "historic", "Virginia Peninsula", 37.2090, -76.7770,
 "At the first General Assembly of the Virginia colony in 1619, legislators passed Acte 12, requiring every householder to plant and maintain ten grapevines. French vignerons were later recruited, but disease defeated the vinifera.", cls="1619", q="approx"))
S.append(site("mother-vine", "us", "The Mother Vine (Roanoke Island)", "historic", "North Carolina (no AVA)", 35.9221, -75.6735,
 "A giant Scuppernong vine at Manteo on Roanoke Island, reputed to be about 400 years old and possibly planted by Croatan people or the Roanoke colonists of the 1580s; often called the oldest cultivated grapevine in the United States. It is privately owned.", cls="Reputedly c. 400 years old", q="approx"))
S.append(site("renault-winery", "us", "Renault Winery", "historic", "Outer Coastal Plain", 39.5470, -74.6230,
 "Louis Nicholas Renault, sent by Champagne houses to find an American site for sparkling wine, founded this winery at Egg Harbor City in 1864. It survived Prohibition by selling 'Renault Wine Tonic' in pharmacies and is one of the oldest continuously operating wineries in the US.", cls="Founded 1864", q="approx"))
S.append(site("biltmore", "us", "Biltmore Estate Winery", "estate", "North Carolina (no AVA)", 35.5457, -82.5582,
 "The Vanderbilt family's estate at Asheville opened a winery in the old dairy barn in 1985; it is often described as the most visited winery in the United States, though much of its fruit comes from California and Washington.", producers=["Biltmore"]))
save_part("p09_midatlantic_south", regions=regions, appellations=A, sites=S)
